(function(g){'use strict';const services=new Map();const norm=n=>String(n||'').trim().toLowerCase().replace(/\s+/g,'-');g.VoidServiceRegistry={version:'2.0.0',register(name,d={}){const key=norm(name);if(!key||typeof d!=='object')return false;services.set(key,{name:key,title:String(d.title||key),path:String(d.path||''),capabilities:Array.isArray(d.capabilities)?d.capabilities.slice():[],available:d.available!==false,invoke:typeof d.invoke==='function'?d.invoke:null,updatedAt:Date.now()});g.VoidEventBus?.emit('service:registered',{name:key});return true},get(name){const s=services.get(norm(name));return s?{...s}:null},list(){return Array.from(services.values(),s=>({name:s.name,title:s.title,path:s.path,capabilities:s.capabilities.slice(),available:s.available,updatedAt:s.updatedAt}))},has(name){const s=services.get(norm(name));return!!(s&&s.available)},invoke(name,payload){const s=services.get(norm(name));if(!s||!s.available||!s.invoke)return g.VoidResultBus?.failure(name,'الخدمة غير متاحة أو لا تملك معالجًا مباشرًا.')||{ok:false,message:'الخدمة غير متاحة.'};try{return g.VoidResultBus?.success(name,'تم تنفيذ طلب الخدمة.',s.invoke(payload))||{ok:true}}catch(e){return g.VoidResultBus?.failure(name,e.message||'فشل تنفيذ الخدمة.')||{ok:false,message:e.message}}}}})(window);
